def solve(I):
    a=[row[:] for row in I]; H=len(a); W=len(a[0])
    vals=[(r,c) for r in range(H) for c in range(W) if a[r][c]==2]
    rs=[r for r,c in vals]; cs=[c for r,c in vals]
    r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
    mkpos=[(r,c,I[r][c]) for r in range(H) for c in range(W) if I[r][c] not in (0,2)]
    C8={c for r,c,v in mkpos}
    def paint(r,cols):
        for c in cols: a[r][c]=2
    # rect band rows
    for r in range(r0,r1+1):
        mrs=[v for (rr,cc,v) in mkpos if rr==r]
        seg=set(range(c0,c1+1))-C8
        if mrs:
            mc=mrs[0]
            p=max(0,min(mc-1,c0-1))
            paint(r,range(p,c0)); paint(r,list(seg))
            for (rr,cc,v) in mkpos:
                if rr==r and cc==mc: a[r][cc]=v
        else:
            paint(r,range(W))
    # rows below rect
    for r in range(r1+1,H):
        s=set(seg)|{v for (rr,cc,v) in mkpos if rr==r}
        s-=C8
        paint(r,s)
        for (rr,cc,v) in mkpos:
            if rr==r and cc not in seg: a[r][cc]=v
    return a
