import numpy as np, json
def solve(I):
    H,W=len(I),len(I[0]); a=[list(r) for r in I]
    vals=[(r,c) for r in range(H) for c in range(W) if a[r][c]==2]
    rs=[r for r,c in vals]; cs=[c for r,c in vals]
    r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
    marks=[(r,c,a[r][c]) for r in range(H) for c in range(W) if a[r][c] not in (0,2)]
    def paint_seg(r,lo,hi):
        for c in range(lo,hi+1): a[r][c]=2
    below_inside={cc for rr,cc,v in marks if rr>r1 and c0<=cc<=c1}
    for r in range(H):
        mc=[cc for rr,cc,v in marks if rr==r]
        if r<r0:
            paint_seg(r,c0,c1)                     # copy rect span upward
        elif r>r1:
            s=set(range(c0,c1+1))-below_inside
            for c in sorted(s): a[r][c]=2
            for (rr,cc,v) in marks:
                if rr==r and cc not in s: a[r][cc]=v
        else:   # inside band rows
            if not mc:
                paint_seg(r,0,W-1)                 # no marker -> full row
            else:
                outs=[cc for cc in mc if cc<c0 or cc>c1]
                if outs:                            # outside markers: paint opposite side
                    paint_seg(r,(c1+1,W-1) if max(outs)>c1 else (0,c0-1))
                for (rr,cc,v) in marks:
                    if rr==r: a[r][cc]=v           # own marker overwrites
    return a
